#!/usr/bin/env python3
"""Generate an internal per-species editorial review, without publishing research notes."""
import argparse
import hashlib
import json
from pathlib import Path
ROOT = Path(__file__).resolve().parents[2]
DOC = ROOT / 'docs/catalogo'

def main():
    p = argparse.ArgumentParser(description=__doc__)
    p.add_argument('--browser-tests', default='Em execução; resultado final será registrado antes da entrega.')
    a = p.parse_args()
    animals = sorted((json.loads(f.read_text()) for f in (ROOT/'src/data/species').glob('*.json')), key=lambda x:x.get('sortOrder',x['source']['row']))
    ledger = json.loads((DOC/'revisao-editorial.json').read_text())
    checks = json.loads((DOC/'revisao-fontes.json').read_text())
    checked = {(x['slug'], x['referenceId']):x for x in checks['checks']}
    reviewed = [x for x in animals if x['slug'] in ledger['records']]
    pending = [x for x in animals if x['slug'] not in ledger['records']]
    for animal in reviewed:
        r = ledger['records'][animal['slug']]
        assert hashlib.sha256((ROOT/r['file']).read_bytes()).hexdigest() == r['afterSha256'], 'Review hash differs: '+animal['slug']
    lines = ['# Revisão editorial e técnica das fichas de espécies','',f"Data de consulta: {ledger['date']}. Branch: `feat/expandir-catalogo-especies`; PR #7. Não autoriza merge nem publicação em produção.",'','## Abrangência','',f'- Fichas identificadas automaticamente: **{len(animals)}**.',f'- Fichas revisadas individualmente: **{len(reviewed)}**, em três lotes de 15.',f'- Fichas ainda não revisadas nesta etapa: **{len(pending)}**.', '- URLs, nomes científicos, categorias, fotografias e licenças preservados; nenhum novo animal cadastrado.', '- A ordem das seções e os resumos são verificados também no contrato dos dados e nos testes do navegador.','', '## Correções editoriais e de estrutura','', '- Texto de pesquisa e justificativas internas retirados das páginas. Informações desconhecidas não viraram promessas; limites e divergências ficam neste relatório.', '- As 14 seções seguem a sequência solicitada no conteúdo e no menu. Apresentação, água e criação ficam abertas; referências continuam fora de seções fechadas.', '- O quadro após Apresentação contém temperatura, pH, GH, tamanho, volume contextualizado, comportamento, sociabilidade, dieta e dificuldade. Valores coincidem com o conteúdo detalhado; quando não existe mínimo defensável em litros, o quadro remete ao dimensionamento específico em vez de inventar um número.', '- Dificuldade é uma síntese editorial das exigências verificadas (estabilidade, alimentação, porte e territorialidade), não uma escala científica validada nem garantia de sucesso.', '- Descrições de montagem antes repetidas em água, criação e saúde foram separadas. Prevenção é específica, sem diagnósticos ou receitas de medicamentos.', '- Navegação móvel recolhível, referências completas, HTML inicial com todo o conteúdo, logo, assinatura e WhatsApp preservados. A barra de contato ficou mais compacta no celular; áreas de rolagem e âncoras respeitam sua altura.', '- A API pública recebe os resumos estruturados. O esquema permanece compatível por adição de campo, sem incluir informações privadas.','', '## Pesquisa, fontes e limites','',f"- {len(checks['checks'])} URLs individuais reconferidas: {sum(x.get('status')==200 for x in checks['checks'])} respostas HTTP 200; cinco páginas FishBase responderam HTTP 503 nesta rodada.", '- Cada espécie possui manutenção específica do Seriously Fish e registro taxonômico individual do Catalog of Fishes reconferidos. A classificação por família e os registros GBIF completam a rastreabilidade; fontes de taxonomia não foram usadas como prova de volume mínimo.', '- Aquarismo Paulista foi tentado como referência editorial, mas o proxy retornou erro de túnel HTTP 403. Nenhum texto, imagem, identidade visual ou dado foi atribuído a uma página inacessível.', '- FishBase havia sido consultado na etapa anterior para as cinco fichas originais; não foi tratado como novamente acessível. Dados relevantes foram mantidos com suas referências e limitações declaradas.', '- Não houve médias automáticas entre parâmetros. Comprimento padrão exclui a cauda; comprimento total não é intercambiável. Valores em milímetros foram convertidos para centímetros na mesma medida, sem estimar crescimento adicional.', '- Faixas amplas de uma referência não significam que se deva alternar os extremos. Volume bruto e base não são uma regra automática de lotação; contexto do grupo e território permanece no texto.', '- Relações geográficas continuam rotuladas como tal; nenhum novo par recebeu aprovação de convivência.','', '## Pendências e decisões importantes','', '- Agulhinha-prata: divergência grande entre 5,5 cm de comprimento padrão e registro de 16,1 cm de comprimento total ainda não foi reconciliada. O texto alerta para o porte; confirmar identificação/população do lote antes de definir a lotação.', '- Venustus: retirados 205 L como recomendação geral para adulto/grupo. Necessário dimensionamento especializado; não foi inventado um novo mínimo.', '- Acará-heckelii: base de 150 × 45 cm para casal, sem extrapolar altura/volume. Grupo demanda muito mais espaço.', '- Zebra-laranja, tricogáster-azul e leeri: limites inferiores históricos não são apresentados como garantia para grupos adultos.', '- Pangasius e pirarara: mantidos como peixes de instalação especializada; a escala em milhares de litros não autoriza tratá-los como adequados ao aquário doméstico.', '- KH específico de manutenção e longevidade sem documentação foram omitidos dos campos públicos, sem derivar KH de GH nem inventar anos de vida. Não foram criados mínimos de grupo ou protocolos de reprodução ausentes das fontes.', '- Micro-habitat pouco documentado em sumatra, bandeira, molinésia-sphenops, tetra-limão e foguinho não foi preenchido com inferências de congêneres.', '- Identificação de linhagens, procedência de lotes, variantes e subdivisões geográficas exige confirmação da loja quando relevante; as fotos são referências da espécie, não comprovação de estoque.', '- O estado de indexação é tratado separadamente na [auditoria de SEO](indexacao-especies.md). A revisão de conteúdo não libera automaticamente todas as fichas. Não existem selos de validação ou mensagens provisórias na interface.', '', '## Validações','', '- `npm run check`: sem erros, avisos ou hints.', '- `npm run build`: 45 fichas, catálogo e demais rotas estáticas.', '- `npm run catalog:audit`: unicidade, hashes, fotografias, atribuições e rastreabilidade.', '- `npm run test:import`: cinco testes: dois de importação OOXML e três de proteção editorial.', f'- Navegador: {a.browser_tests}', '', '## Revisão por espécie','']
    for animal in reviewed:
        slug=animal['slug'];r=ledger['records'][slug];facts={x['key']:x['value'] for x in animal['essentials']}
        lines += [f"### {animal['name']} — {animal['scientificName']}",'',f"- URL preservada: `/especies/{slug}/`; lote editorial {r['batch']}.",f"- Água: {facts['temperature']}; pH {facts['ph']}; GH {facts['gh']}.",f"- Porte e espaço: {facts['size']}; {facts['volume']}.",f"- Manejo: {facts['behavior']}; {facts['sociability']}; {facts['diet']}.",f"- Decisão: {r['decision']}",'- Dados/avaliações que exigem cautela: '+' '.join(r['unverified']),'- Fontes individuais:']
        for ref in animal['references']:
            check=checked.get((slug,ref['id']));status=f" — HTTP {check['status']} reconferido" if check and check.get('status')==200 else ' — indisponível nesta rodada; consulta anterior preservada' if check else ' — referência complementar já registrada'
            lines.append(f"  - [{ref['title']}]({ref['url']}){status}.")
        lines.append('')
    if pending:
        lines += ['## Fichas a retomar','']+[f"- {x['name']} — {x['scientificName']}" for x in pending]+['']
    lines += ['## Arquivos e retomada','', '- `docs/catalogo/revisao-editorial.json`: cobertura dos lotes, decisões, hashes anteriores/posteriores e fontes por espécie.', '- `docs/catalogo/revisao-fontes.json`: respostas reais e hashes das páginas acessadas, incluindo falhas.', '- `docs/catalogo/preservados.json`: baseline original imutável das cinco fichas do PR #6; mudanças agora autorizadas são justificadas no ledger editorial, sem apagar o histórico.', '- `src/data/species/*.json`: fonte única dos dados públicos revisados e dos resumos.', '- `scripts/catalog/report_editorial.py`: gera este relatório a partir dos dados e da trilha de revisão.', '- `docs/catalogo-pendencias.md`: continua sendo o relatório da expansão da planilha (123 registros para próxima etapa); esta revisão não os cadastra.', '- Não há publicação de produção nesta etapa. Conferir o preview do commit e aguardar aprovação da loja.','']
    (ROOT/'docs/revisao-editorial-especies.md').write_text('\n'.join(lines))
    print(json.dumps({'identified':len(animals),'reviewed':len(reviewed),'pending':len(pending)}))
if __name__=='__main__':main()
